#include <stdio.h>

enum Day { MON, TUE, WED, THU, FRI, SAT, SUN };

int main() {
    enum Day today = WED;
    printf("Day number: %d\n", today);
    if (today == SAT || today == SUN) {
        printf("Weekend\n");
    } else {
        printf("Weekday\n");
    }
    return 0;
}
